class Solution {
    public String crackSafe(int n, int k) {
        if (n == 1) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < k; i++) sb.append(i);
            return sb.toString();
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n - 1; i++) sb.append('0');
        String start = sb.toString();
        sb.setLength(0);
        java.util.Set<String> visited = new java.util.HashSet<>();
        dfs(start, k, visited, sb);
        sb.append(start);
        return sb.toString();
    }
    private void dfs(String node, int k, java.util.Set<String> visited, StringBuilder sb) {
        for (int i = 0; i < k; i++) {
            String edge = node + i;
            if (visited.add(edge)) {
                dfs(edge.substring(1), k, visited, sb);
                sb.append(i);
            }
        }
    }
}

import java.util.*;

class Solution {
    public String crackSafe(int n, int k) {
        if (n == 1) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < k; i++) sb.append(i);
            return sb.toString();
        }
        Set<String> visited = new HashSet<>();
        StringBuilder start = new StringBuilder();
        for (int i = 0; i < n - 1; i++) start.append('0');
        Deque<String> stack = new ArrayDeque<>();
        List<Integer> path = new ArrayList<>();
        stack.push(start.toString());
        while (!stack.isEmpty()) {
            String node = stack.peek();
            boolean found = false;
            for (int i = 0; i < k; i++) {
                String edge = node + i;
                if (!visited.contains(edge)) {
                    visited.add(edge);
                    stack.push(edge.substring(1));
                    found = true;
                    break;
                }
            }
            if (!found) {
                stack.pop();
                if (!stack.isEmpty()) {
                    path.add(node.charAt(node.length() - 1) - '0');
                }
            }
        }
        StringBuilder result = new StringBuilder();
        for (int i = path.size() - 1; i >= 0; i--) {
            result.append(path.get(i));
        }
        result.append(start);
        return result.toString();
    }
}
